--region public
---@param rewardVo WorldBossHurtRewardVo
function UIWorldBossDamageRewardCell:Refresh(rewardVo)
    self._rewardVo = rewardVo

    self._rewards = {}
    local rewardCount = #self._rewardVo.reward
    for i = 1, rewardCount do
        local reward = {
            goodsId = self._rewardVo.reward[i],
            num = self._rewardVo.rewardNum[i]
        }
        table.insert(self._rewards, reward)
    end

    self:RefreshTxtDamage()
    self:RefreshDamageRewards()
    self:RefreshBtnType()

    CfUtils.PlayAnimator(self.AnimRoot, "Go")
end

function UIWorldBossDamageRewardCell:SetDrawRewardCallback(cb)
    self.cb = cb
end
--endregion public

--region private
function UIWorldBossDamageRewardCell:OnBtnDrawRewardHandler()
    WorldBossEntityMgr:WorldBossDrawRewardReq(self._rewardVo.id)
end
--endregion private

--region get / set
function UIWorldBossDamageRewardCell:RefreshBtnType()
    local initDojo = self._worldBossComp:GetWorldBossInitDojo()

    if isNull(initDojo) then
        return
    end

    if initDojo.historyMaxHurt < checkNumber(self._rewardVo.upperLimit) then
        -- 不可领取
        CfUtils.SetActive(self.TxtNo, true)
        CfUtils.SetActive(self.FontStyleButton, false)
        CfUtils.SetActive(self.Finish, false)
        return
    end
    CfUtils.SetActive(self.TxtNo, false)
    CfUtils.SetActive(self.FontStyleButton, not initDojo:IsHaveDraw(self._rewardVo.id))
    CfUtils.SetActive(self.Finish, initDojo:IsHaveDraw(self._rewardVo.id))
    if not initDojo:IsHaveDraw(self._rewardVo.id) then
        SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnDrawRewardHandler))
    end
end

function UIWorldBossDamageRewardCell:RefreshTxtDamage()
    CfUtils.FillText(self.TxtDamage, self._rewardVo.upperLimit)
end

function UIWorldBossDamageRewardCell:RefreshDamageRewards()
    ---@type CommonGoodsList
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
    scr:FreshBaseUI(self._rewards)
end
--endregion get / set

return UIWorldBossDamageRewardCell
